// Why: the table-driven Exp, Log and Pow (std/math/exptab.mk, logtab.mk,
// pow.mk) need tables exact to the last bit, generated from math/big.
// What: the generators and TestSTDMATH_Tables; MK_MATH_GEN=write rewrites.
// How: each block sits between "// Generated by TestSTDMATH_Tables (<name>)"
// and "// End of the generated block (<name>).", and must be exactly what
// the generator writes; the generator also checks the properties the code
// relies on (exact products and sums, the reduced argument's bound).

package std

import (
	"fmt"
	"math"
	"math/big"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// mathGenPrec is the working precision of the generator.
const mathGenPrec = 600

// mathGenN is the table size of Exp, Log and Pow's logarithm (2^7).
const mathGenN = 128

// mathRN is x rounded to the nearest f64, ties to even.
func mathRN(x *big.Float) float64 {
	f, _ := new(big.Float).SetPrec(53).SetMode(big.ToNearestEven).Set(x).Float64()
	return f
}

// mathRound is x rounded to the nearest multiple of 2^-q, ties to even.
func mathRound(x *big.Float, q int) *big.Float {
	if x.Sign() == 0 {
		return bnp(mathGenPrec)
	}
	e := x.MantExp(nil) // 2^(e-1) <= |x| < 2^e
	bits := e + q
	if bits <= 0 {
		// |x| < 2^-q: 0, or 2^-q when |x| > 2^-q / 2.
		h := new(big.Float).SetMantExp(big.NewFloat(1), -q-1)
		if new(big.Float).Abs(x).Cmp(h) > 0 {
			return new(big.Float).SetPrec(mathGenPrec).SetMantExp(big.NewFloat(float64(x.Sign())), -q)
		}
		return bnp(mathGenPrec)
	}
	r := new(big.Float).SetPrec(uint(bits)).SetMode(big.ToNearestEven).Set(x)
	return new(big.Float).SetPrec(mathGenPrec).Set(r)
}

// mathSigBits is the number of significant bits of a finite nonzero f64.
func mathSigBits(x float64) int {
	b := math.Float64bits(x)
	m := b & (1<<52 - 1)
	if (b>>52)&0x7FF != 0 {
		m |= 1 << 52
	}
	n := 0
	for m != 0 && m&1 == 0 {
		m >>= 1
	}
	for m != 0 {
		m >>= 1
		n++
	}
	return n
}

// mathBits formats x as an f64.FromBits constant.
func mathConst(name string, x float64, what string) string {
	return fmt.Sprintf("// %s\nconst %s: f64 = f64.FromBits(0x%016X)\n", what, name, math.Float64bits(x))
}

// mathTable formats a [n]u64 table, per words to a line.
func mathTable(name string, words []uint64, per int) string {
	var sb strings.Builder
	fmt.Fprintf(&sb, "const %s: [%d]u64 = [\n", name, len(words))
	for i := 0; i < len(words); i += per {
		sb.WriteString("    ")
		for j := i; j < i+per && j < len(words); j++ {
			if j > i {
				sb.WriteString(" ")
			}
			fmt.Fprintf(&sb, "0x%016X,", words[j])
		}
		sb.WriteString("\n")
	}
	sb.WriteString("]\n")
	return sb.String()
}

// mathLogInterval is the subinterval [a, b) of z in [0.6875, 1.375) that
// row i of a logarithm table covers: z's bits less 0x3FE6000000000000 have
// i in bits 45 to 51 (and the exponent above), so rows 0 to 79 split
// [0.6875, 1) in steps of 2^-8 and rows 80 to 127 split [1, 1.375) in steps
// of 2^-7.
func mathLogInterval(i int) (a, b float64) {
	lo := math.Float64frombits(0x3FE6000000000000 + uint64(i)<<45)
	hi := math.Float64frombits(0x3FE6000000000000 + uint64(i+1)<<45)
	return lo, hi
}

// mathGenBlocks is the text of every generated block, by name, and an
// error for a property the Mk code relies on that the tables break.
func mathGenBlocks() (map[string]string, []string) {
	p := uint(mathGenPrec)
	var bad []string
	ln2 := bigLn2At(p)
	out := map[string]string{}

	// Exp: x = (128 k + i) ln2/128 + r.
	{
		var sb strings.Builder
		ln2n := bnp(p).Quo(ln2, bfp(mathGenN, p))
		inv := mathRN(bnp(p).Quo(bfp(mathGenN, p), ln2))
		hi := mathRN(mathRound(ln2n, 7+34)) // 34 significant bits (ln2/128 < 2^-7)
		lo := mathRN(bnp(p).Sub(ln2n, bfp(hi, p)))
		if mathSigBits(hi) > 34 {
			bad = append(bad, fmt.Sprintf("exp: ExpLn2HiN has %d bits, want <= 34 (k * ExpLn2HiN exact for |k| < 2^19)", mathSigBits(hi)))
		}
		sb.WriteString(mathConst("ExpInvLn2N", inv, "128 / ln2."))
		sb.WriteString(mathConst("ExpLn2HiN", hi, "ln2 / 128 to 34 bits, so k * ExpLn2HiN is exact for |k| < 2^19."))
		sb.WriteString(mathConst("ExpLn2LoN", lo, "ln2 / 128 less ExpLn2HiN."))
		sb.WriteString(mathConst("ExpQ2", mathRN(bnp(p).Quo(bfp(1, p), bfp(2, p))), "1/2!: e^r - 1 - r = r^2 (ExpQ2 + r ExpQ3 + r^2 (ExpQ4 + r ExpQ5)), truncation below 2^-60 for |r| <= ln2/256."))
		sb.WriteString(mathConst("ExpQ3", mathRN(bnp(p).Quo(bfp(1, p), bfp(6, p))), "1/3!."))
		sb.WriteString(mathConst("ExpQ4", mathRN(bnp(p).Quo(bfp(1, p), bfp(24, p))), "1/4!."))
		sb.WriteString(mathConst("ExpQ5", mathRN(bnp(p).Quo(bfp(1, p), bfp(120, p))), "1/5!."))
		words := make([]uint64, 0, 2*mathGenN)
		for i := 0; i < mathGenN; i++ {
			x := bnp(p).Mul(ln2n, bfp(float64(i), p))
			s := bigExpP(x, p)
			sh := mathRN(s)
			tail := mathRN(bnp(p).Quo(bnp(p).Sub(s, bfp(sh, p)), bfp(sh, p)))
			words = append(words, math.Float64bits(tail), math.Float64bits(sh)-uint64(i)<<45)
		}
		sb.WriteString("// For i in 0..128, 2^(i/128) as h (1 + t): t's bits, then h's bits less\n// i << 45, so adding k << 45 for k = 128 m + i puts m in the exponent.\n")
		sb.WriteString(mathTable("ExpT", words, 2))
		out["exp"] = sb.String()
	}

	// ln2 on the grid of 2^-42, so k * ln2hi + a table's log c (on the same
	// grid) is exact for |k| <= 1100.
	l2hi := mathRN(mathRound(ln2, 42))
	l2lo := mathRN(bnp(p).Sub(ln2, bfp(l2hi, p)))

	// Log: z in row i's interval, c = 1 / invc, r = (z - chi - clo) invc.
	{
		var sb strings.Builder
		sb.WriteString(mathConst("LogLn2Hi", l2hi, "ln2 on the grid of 2^-42, so k * LogLn2Hi + a row's log c head is exact."))
		sb.WriteString(mathConst("LogLn2Lo", l2lo, "ln2 less LogLn2Hi."))
		words := make([]uint64, 0, 5*mathGenN)
		var rmax float64
		for i := 0; i < mathGenN; i++ {
			a, b := mathLogInterval(i)
			center := bnp(p).Add(bfp(a, p), bfp(b, p))
			center.Quo(center, bfp(2, p))
			invc := mathRN(bnp(p).Quo(bfp(1, p), center))
			c := bnp(p).Quo(bfp(1, p), bfp(invc, p))
			chi := mathRN(c)
			clo := mathRN(bnp(p).Sub(c, bfp(chi, p)))
			logc := bigLogP(c, p)
			lchi := mathRound(logc, 42)
			lclo := mathRN(bnp(p).Sub(logc, lchi))
			words = append(words, math.Float64bits(invc), math.Float64bits(chi), math.Float64bits(clo),
				math.Float64bits(mathRN(lchi)), math.Float64bits(lclo))
			// z - chi must be exact (Sterbenz: chi / 2 <= z <= 2 chi).
			if chi/2 > a || 2*chi < b {
				bad = append(bad, fmt.Sprintf("log row %d: z - chi is not exact on [%v, %v)", i, a, b))
			}
			for _, z := range []float64{a, math.Nextafter(b, 0)} {
				r := math.Abs((z - chi - clo) * invc)
				rmax = math.Max(rmax, r)
			}
		}
		if rmax > 0x1p-8 {
			bad = append(bad, fmt.Sprintf("log: |r| reaches %g, above 2^-8", rmax))
		}
		sb.WriteString(mathConst("LogA2", -0.5, "-1/2: log1p(r) - r = r^2 (LogA2 + r LogA3 + ...), Taylor's series to r^7, truncation below 2^-64 for |r| <= 2^-8."))
		sb.WriteString(mathConst("LogA3", mathRN(bnp(p).Quo(bfp(1, p), bfp(3, p))), "1/3."))
		sb.WriteString(mathConst("LogA4", -0.25, "-1/4."))
		sb.WriteString(mathConst("LogA5", mathRN(bnp(p).Quo(bfp(1, p), bfp(5, p))), "1/5."))
		sb.WriteString(mathConst("LogA6", mathRN(bnp(p).Quo(bfp(-1, p), bfp(6, p))), "-1/6."))
		sb.WriteString(mathConst("LogA7", mathRN(bnp(p).Quo(bfp(1, p), bfp(7, p))), "1/7."))
		sb.WriteString("// For each row i (mathLogInterval): invc, the f64 nearest 1 / the\n// interval's center; c = 1 / invc as chi + clo; log c as a head on the grid\n// of 2^-42 and a tail.\n")
		sb.WriteString(mathTable("LogT", words, 5))
		out["log"] = sb.String()
	}

	// Pow's logarithm: invc with at most 8 significant bits (1 for the two
	// rows beside 1), so z invc - 1 is an f64 for every z of the row (53
	// bits from 2^-8 down to 2^-60) and zhi invc and zlo invc are exact.
	{
		var sb strings.Builder
		words := make([]uint64, 0, 3*mathGenN)
		var rmax float64
		for i := 0; i < mathGenN; i++ {
			a, b := mathLogInterval(i)
			var invc float64
			if i == 79 || i == 80 {
				invc = 1
			} else {
				center := bnp(p).Add(bfp(a, p), bfp(b, p))
				center.Quo(center, bfp(2, p))
				inv := bnp(p).Quo(bfp(1, p), center)
				invc = mathRN(mathRound(inv, 8-inv.MantExp(nil)))
			}
			if mathSigBits(invc) > 8 {
				bad = append(bad, fmt.Sprintf("pow row %d: invc has %d bits", i, mathSigBits(invc)))
			}
			logc := bnp(p).Neg(bigLogP(bfp(invc, p), p))
			lchi := mathRound(logc, 42)
			lclo := mathRN(bnp(p).Sub(logc, lchi))
			words = append(words, math.Float64bits(invc), math.Float64bits(mathRN(lchi)), math.Float64bits(lclo))
			var rrow float64
			for _, z := range []float64{a, math.Nextafter(b, 0)} {
				// The exact r = z invc - 1 at the interval's ends.
				exact := bnp(p).Sub(bnp(p).Mul(bfp(z, p), bfp(invc, p)), bfp(1, p))
				r, acc := exact.Float64()
				if acc != big.Exact {
					bad = append(bad, fmt.Sprintf("pow row %d: z invc - 1 is not an f64 at z = %v", i, z))
				}
				rrow = math.Max(rrow, math.Abs(r))
			}
			rmax = math.Max(rmax, rrow)
			// t2 = t1 + rhi as FastTwoSum needs |log c| >= |r| unless c = 1.
			if invc != 1 && math.Abs(mathRN(lchi)) < rrow*1.001 {
				bad = append(bad, fmt.Sprintf("pow row %d: |log c| %g below |r| %g", i, mathRN(lchi), rrow))
			}
		}
		if rmax > 0x1p-7 {
			bad = append(bad, fmt.Sprintf("pow: |r| reaches %g, above 2^-7", rmax))
		}
		for n := 3; n <= 10; n++ {
			v := mathRN(bnp(p).Quo(bfp(1, p), bfp(float64(n), p)))
			if n%2 == 0 {
				v = -v
			}
			what := fmt.Sprintf("(-1)^(n+1)/n for n = %d.", n)
			if n == 3 {
				what = "log1p(r) - r + r^2/2 = r^3 (PowA3 + r PowA4 + ... + r^7 PowA10), Taylor's series, truncation below 2^-73 relative for |r| <= 2^-7; PowA3 = 1/3."
			}
			sb.WriteString(mathConst(fmt.Sprintf("PowA%d", n), v, what))
		}
		sb.WriteString("// For each row i (mathLogInterval): invc with at most 8 significant bits,\n// near 1 / the interval's center (1 for the two rows beside 1), and -log\n// invc as a head on the grid of 2^-42 and a tail.\n")
		sb.WriteString(mathTable("PowLogT", words, 3))
		out["pow"] = sb.String()
	}
	mathGenFast32(p, out, &bad)
	return out, bad
}

// mathGenFiles names the file holding each generated block.
var mathGenFiles = map[string]string{"exp": "exptab.mk", "log": "logtab.mk", "pow": "pow.mk", "fast32": "fast32.mk"}

// TestSTDMATH_Tables requires each generated block in std/math to be the
// generator's text, and the tables to keep the properties the code relies
// on; MK_MATH_GEN=write rewrites the blocks.
func TestSTDMATH_Tables(t *testing.T) {
	blocks, bad := mathGenBlocks()
	for _, b := range bad {
		t.Error(b)
	}
	write := os.Getenv("MK_MATH_GEN") == "write"
	for name, text := range blocks {
		file := filepath.Join("math", mathGenFiles[name])
		src, err := os.ReadFile(file)
		if err != nil {
			t.Fatal(err)
		}
		s := strings.ReplaceAll(string(src), "\r\n", "\n")
		begin := fmt.Sprintf("// Generated by TestSTDMATH_Tables (%s): do not edit.\n", name)
		end := fmt.Sprintf("// End of the generated block (%s).\n", name)
		i := strings.Index(s, begin)
		j := strings.Index(s, end)
		if i < 0 || j < i {
			t.Errorf("%s: no generated block %q", file, name)
			continue
		}
		have := s[i+len(begin) : j]
		if have == text {
			continue
		}
		if write {
			s = s[:i+len(begin)] + text + s[j:]
			if err := os.WriteFile(file, []byte(s), 0o644); err != nil {
				t.Fatal(err)
			}
			t.Logf("%s: block %q rewritten", file, name)
			continue
		}
		t.Errorf("%s: block %q differs from the generator's text (MK_MATH_GEN=write rewrites it)", file, name)
	}
}
